relational.sql<pre><code>CREATE TABLE customers (
    customer_id int PRIMARY KEY,
    customer_name varchar(100),
    country varchar(100)
);
CREATE TABLE orders (
    order_id int PRIMARY KEY,
    customer_id int REFERENCES customers(customer_id),
    order_date date
);

INSERT INTO customers (customer_id, customer_name, country)
    VALUES (1, 'John Smith', 'UK');
INSERT INTO orders (order_id, customer_id, order_date)
    VALUES (1, 1, '2020-01-01');

SELECT *
FROM customers c
INNER JOIN orders o
ON c.customer_id = o.order_id;
</code></pre> customer_id customer_name country order_id customer_id order_date 1 John Smith UK 1 1 2020-01-01

key-value.sql<pre><code>CREATE EXTENSION hstore;
CREATE TABLE books (
    id serial PRIMARY KEY,
    title varchar(255),
    attr hstore
);
INSERT INTO books (title, attr)
    VALUES ('1984',
        '"author" =&gt; "George Orwell",
        "published" =&gt; "1949-06-08",
        "language" =&gt; "English",
        "fiction" =&gt; true');

SELECT title, attr -&gt; 'author' AS author
FROM books
WHERE attr -&gt; 'fiction' = 'true';
</code></pre> title author 1984 George Orwell

document-json.sql<pre><code>CREATE TABLE orders (
    id serial NOT NULL PRIMARY KEY,
    info json NOT NULL
);

INSERT INTO orders (info)
    VALUES (
        '{"customer": "James", "items": [
            {
                "product": "coffee",
                "qty": 4
            }
        ]}'
    );

SELECT
  o.id,
  o.info -&gt;&gt; 'customer' as customer,
  i.value -&gt;&gt; 'product' as product,
  i.value -&gt;&gt; 'qty' as quantity
FROM orders o,
LATERAL json_array_elements(o.info -&gt; 'items') i
</code></pre> document-xml.sql<pre><code>CREATE TABLE orders (
    id serial NOT NULL PRIMARY KEY,
    info xml NOT NULL
);

INSERT INTO orders (info)
VALUES (
  '&lt;order&gt;
    &lt;customer&gt;James&lt;/customer&gt;
    &lt;items&gt;
      &lt;item product="coffee" qty="4" /&gt;
    &lt;/items&gt;
  &lt;/order&gt;'
);

SELECT id,
  (xpath('order/customer/text()', info))[1] AS customer,
  (xpath('order/items/item/@product', info))[1] AS product,
  (xpath('order/items/item/@qty', info))[1] AS quantity
FROM orders;
</code></pre> id customer product quantity 1 James coffee 4

